// Runs once per new row. The keys are the sheet's header row: Invoice,
// Client, Email, Description, Quantity, Unit price, Due date. Rename them here
// if your headers differ.
const row = $json;

const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const qty = Number(row['Quantity'] || 0);
const price = Number(row['Unit price'] || 0);
const amount = (qty * price).toFixed(2);

const html = `<!doctype html>
<html><head><meta charset="utf-8"><style>
@page { size: A4; margin: 22mm;
  @bottom-center { content: "Page " counter(page) " of " counter(pages); font: 8pt sans-serif; color: #6b7480 } }
body { font: 11pt/1.5 "DejaVu Sans", sans-serif; color: #1c2024 }
h1 { font-size: 20pt; margin: 0 0 2mm }
.meta { color: #6b7480; margin-bottom: 10mm }
table { width: 100%; border-collapse: collapse }
th { text-align: left; border-bottom: 2px solid #1c2024 }
td { padding: 3mm 0; border-bottom: 1px solid #e3e6ea }
.num { text-align: right }
</style></head><body>
<h1>Invoice ${esc(row['Invoice'])}</h1>
<p class="meta">${esc(row['Client'])} · Due ${esc(row['Due date'])}</p>
<table>
  <thead><tr><th>Description</th><th class="num">Qty</th><th class="num">Unit price</th><th class="num">Amount</th></tr></thead>
  <tbody>
    <tr><td>${esc(row['Description'])}</td><td class="num">${esc(qty)}</td><td class="num">${price.toFixed(2)}</td><td class="num">${amount}</td></tr>
  </tbody>
</table>
</body></html>`;

const id = String(row['Invoice'] ?? 'document').replace(/[^A-Za-z0-9_-]/g, '_');
return {
  json: {
    html,
    filename: `invoice-${id}.pdf`,
    email_to: row['Email'] ?? '',
    client: row['Client'] ?? '',
    subject: `Invoice ${row['Invoice'] ?? ''}`.trim(),
  },
};
